function renderGame() {
  // Water Background
  background(10, 20, 60);

  rectMode(CORNER);
  // Surface Layer
  fill(30, 80, 120);
  rect(0, 0, width, 70);

  // Oxygen Bar Background
  fill(0);
  rect(0, height - 10, width, 10);
  // Oxygen Bar Fill
  fill(0, 255, 255);
  rect(0, height - 10, (player.oxygen / 100) * width, 10);

  // Collected Divers Indicators (top left)
  fill(0, 255, 0);
  for (let i = 0; i < player.diverCount; i++) {
    rect(10 + i * 14, 10, 10, 10);
  }

  rectMode(CENTER);
  noStroke();

  // Draw Divers
  fill(0, 255, 0);
  for (let d of divers) {
    rect(d.x, d.y, d.w, d.h);
  }

  // Draw Enemies
  for (let e of enemies) {
    if (e.type === 'sub') {
      fill(220, 20, 60); // Red for sub
    } else {
      fill(120, 0, 120); // Purple for shark
    }
    rect(e.x, e.y, e.w, e.h);
    // Draw snout/tail to indicate direction
    let dir = e.vx > 0 ? 1 : -1;
    rect(e.x + (dir * e.w * 0.4), e.y - 2, e.w * 0.4, e.h * 0.4);
  }

  // Draw Player Bullets
  fill(255, 255, 0);
  for (let b of pBullets) {
    rect(b.x, b.y, b.w, b.h);
  }

  // Draw Enemy Bullets
  fill(255, 100, 0);
  for (let b of eBullets) {
    rect(b.x, b.y, b.w, b.h);
  }

  // Draw Player
  if (gameState === 'PLAYING') {
    fill(0, 150, 255);
    rect(player.x, player.y, player.w, player.h);
    // Player gun barrel
    rect(player.x + (player.facing * 12), player.y, 8, 4);
  }
}
```

